if __name__ == '__main__':
    json_paths = natsorted(glob('outputs/apartment-5-seq-tiny-25views/*/solve_state.json'))

    for json_path in json_paths:
        with open(json_path, 'r') as f:
            data = json.load(f)
        
        counts = defaultdict(int)
        category_counts = defaultdict(int)

        for obj_id, obj in data['objs'].items():
            if '_' in obj_id and '/' not in obj_id:
                counts[obj_id.split('_')[1]] += 1
                if obj_id.split('_')[1] not in factories_category:
                    print(f'Unknown object: {obj_id}')
                category = factories_category.get(obj_id.split('_')[1], 'unknown')
                category_counts[category] += 1

        counts = natsorted(counts.items(), lambda x: x[1], reverse=True)
        category_counts = natsorted(category_counts.items(), lambda x: x[1], reverse=True)

        pprint(counts)
        pprint(category_counts)
        print('---')